  let encoded = textureLoad(hdrEnvironmentTexture, safePixel, 0);
  let movingHillHostLinearHdr = params.hostFrameControls.x > 0.5;
  return select(decodeRgbe(encoded), encoded.rgb, movingHillHostLinearHdr);
